<?php
declare(strict_types=1);
return ['command'=>'chk','description'=>'Run synthetic sandbox scenario','handler'=>static function(array $c):void{$input=trim($c['arguments']);if(str_contains($input,'|')||preg_match('/\b\d{12,19}\b/',$input)===1){bot_send($c['chat_id'],"🛡️ This sandbox does not accept payment-card numbers, expiry dates, or CVVs.\n\nUse <code>/chk DEMO-1234</code> for a synthetic scenario.");return;}if(preg_match('/^DEMO-[A-Z0-9]{4,12}$/i',$input)!==1){bot_send($c['chat_id'],'Usage: <code>/chk DEMO-1234</code>. Only synthetic demo IDs are accepted.');return;}$safe=htmlspecialchars(strtoupper($input),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');bot_send($c['chat_id'],"🧪 <b>Sandbox check result</b>\nReference: <code>{$safe}</code>\nResult: <code>SIMULATED_ONLY</code>\nNo card, bank, BIN, or payment gateway was contacted.");}];